DELETE FROM file_favorites
WHERE user_id = CAST(#{userId, jdbcType=VARCHAR} AS uuid)
  AND path = #{path, jdbcType=VARCHAR}

mapper.update:

UPDATE file_favorites
SET path = CASE WHEN path = #{source, jdbcType=VARCHAR}
                THEN #{destination, jdbcType=VARCHAR}
                ELSE CONCAT(#{destination, jdbcType=VARCHAR},
                            SUBSTRING(path FROM LENGTH(#{source, jdbcType=VARCHAR}) + 1))
           END
WHERE user_id = CAST(#{userId, jdbcType=VARCHAR} AS uuid)
  AND (path = #{source, jdbcType=VARCHAR}
       OR path LIKE CONCAT(#{escapedSource, jdbcType=VARCHAR}, '/%') ESCAPE CHR(92))


